import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        Subscription[] subs = new Subscription[n];
        int[] months = new int[n];
        for (int i = 0; i < n; i++) {
            String type = sc.next();
            int id = Integer.parseInt(sc.next());
            long fee = Long.parseLong(sc.next());
            months[i] = Integer.parseInt(sc.next());
            if (type.equals("S")) {
                subs[i] = new StandardSubscription(id, fee);
            } else {
                subs[i] = new PremiumSubscription(id, fee);
            }
        }
        long total = 0;
        for (int i = 0; i < n; i++) {
            long bill = subs[i].calculateBill(months[i]);
            total += bill;
            System.out.println("Customer " + subs[i].getCustomerId() + ": " + bill);
        }
        System.out.println("Total Bill: " + total);
    }
}

abstract class Subscription {
    private int customerId;
    private long monthlyFee;

    Subscription(int customerId, long monthlyFee) {
        this.customerId = customerId;
        this.monthlyFee = monthlyFee;
    }

    public int getCustomerId() {
        return customerId;
    }

    public long getMonthlyFee() {
        return monthlyFee;
    }

    public abstract long calculateBill(int months);
}

class StandardSubscription extends Subscription {
    StandardSubscription(int customerId, long monthlyFee) {
        super(customerId, monthlyFee);
    }

    @Override
    public long calculateBill(int months) {
        return getMonthlyFee() * months;
    }
}

class PremiumSubscription extends Subscription {
    PremiumSubscription(int customerId, long monthlyFee) {
        super(customerId, monthlyFee);
    }

    @Override
    public long calculateBill(int months) {
        if (months == 0) {
            return 0;
        }
        return getMonthlyFee() * months + 500;
    }
}

