public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        ShoppingCart cart = new ShoppingCart(n);
        for (int i = 0; i < n; i++) {
            String name = sc.next();
            long price = Long.parseLong(sc.next());
            int quantity = Integer.parseInt(sc.next());
            CartItem item = new CartItem(name, price, quantity);
            cart.addItem(item);
            System.out.println(item.getProductName() + ": " + item.subtotal());
        }
        System.out.println("Cart Total: " + cart.calculateTotal());
    }
}

class CartItem {
    private String productName;
    private long unitPrice;
    private int quantity;

    CartItem(String productName, long unitPrice, int quantity) {
        this.productName = productName;
        this.unitPrice = unitPrice;
        this.quantity = quantity;
    }

    public String getProductName() {
        return productName;
    }

    public long subtotal() {
        return unitPrice * quantity;
    }
}

class ShoppingCart {
    private CartItem[] items;
    private int count;

    ShoppingCart(int capacity) {
        items = new CartItem[capacity];
        count = 0;
    }

    public void addItem(CartItem item) {
        items[count] = item;
        count++;
    }

    public long calculateTotal() {
        long total = 0;
        for (int i = 0; i < count; i++) {
            total += items[i].subtotal();
        }
        return total;
    }
}

