        int n = Integer.parseInt(sc.next());
        Product[] products = new Product[n];
        int distinct = 0;
        for (int i = 0; i < n; i++) {
            products[i] = new Product(Integer.parseInt(sc.next()), sc.next());
            boolean seen = false;
            for (int j = 0; j < i; j++) {
                if (products[i].equals(products[j])) {
                    seen = true;
                    break;
                }
            }
            if (!seen) {
                distinct++;
            }
        }
        System.out.println(distinct);
    }
}

class Product {
    private int productId;
    private String name;

    Product(int productId, String name) {
        this.productId = productId;
        this.name = name;
    }

    @Override
    public boolean equals(Object obj) {
        if (!(obj instanceof Product)) {
            return false;
        }
        return productId == ((Product) obj).productId;
    }

    @Override
    public int hashCode() {
        return productId;
    }
}
